-- Versioned legal notices and encrypted, owner-controlled runtime configuration.
create table public.ig_policy_releases(
 version text primary key check(length(version) between 3 and 60), documents jsonb not null,
 sha256 text not null, current boolean not null default false, legal_reviewed boolean not null default false,
 created_by uuid references auth.users(id), created_at timestamptz not null default now()
);
create unique index ig_policy_current on public.ig_policy_releases(current) where current;
alter table public.ig_policy_releases enable row level security;
revoke all on public.ig_policy_releases from anon,authenticated;
grant select on public.ig_policy_releases to anon,authenticated;
create policy policy_public_read on public.ig_policy_releases for select to anon,authenticated using(current and legal_reviewed);
create index ig_policy_creator on public.ig_policy_releases(created_by);
alter table public.ig_consents add column policy_hash text;
create function ig_private.current_policy() returns text language sql stable security definer set search_path='' as $$
 select version from public.ig_policy_releases where current
$$;
revoke all on function ig_private.current_policy() from public,anon;
grant execute on function ig_private.current_policy() to authenticated;

create table ig_private.integration_config(
 id text primary key check(id in ('business','resend','razorpay','fast2sms','openai')),
 mode text not null, settings jsonb not null default '{}', sealed jsonb not null default '{}',
 credential_fields text[] not null default '{}', version integer not null default 1,
 updated_by uuid references auth.users(id),updated_at timestamptz not null default now()
);
create table ig_private.integration_root(id boolean primary key default true check(id),secret_hash text not null);
alter table ig_private.integration_config enable row level security;
alter table ig_private.integration_root enable row level security;
revoke all on ig_private.integration_config,ig_private.integration_root from public,anon,authenticated;
create index ig_config_updater on ig_private.integration_config(updated_by);
create function ig_private.integration_server(secret text) returns boolean language sql stable security definer set search_path='' as $$
 select length(secret)=64 and exists(select 1 from ig_private.integration_root where secret_hash=encode(extensions.digest(convert_to(secret,'UTF8'),'sha256'),'hex'))
$$;
revoke all on function ig_private.integration_server(text) from public,anon,authenticated;
create function ig_private.config_runtime(secret text) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if not ig_private.integration_server(secret) then raise exception 'Server authorisation required' using errcode='42501'; end if;
 return coalesce((select jsonb_object_agg(id,to_jsonb(c)-'updated_by') from ig_private.integration_config c),'{}');
end $$;
create function public.ig_config_runtime(secret text) returns jsonb language sql security invoker set search_path='' as $$select ig_private.config_runtime(secret)$$;
revoke all on function ig_private.config_runtime(text),public.ig_config_runtime(text) from public;
grant execute on function ig_private.config_runtime(text),public.ig_config_runtime(text) to anon,authenticated;
create function ig_private.config_list() returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if not ig_private.allowed('settings.manage') then raise exception 'Super-user permission and MFA required' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(to_jsonb(c)-'sealed'-'updated_by' order by id) from ig_private.integration_config c),'[]');
end $$;
create function public.ig_config_list() returns jsonb language sql security invoker set search_path='' as $$select ig_private.config_list()$$;
create function ig_private.config_save(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare c ig_private.integration_config; k text;
begin
 if not ig_private.allowed('settings.manage') then raise exception 'Super-user permission and MFA required' using errcode='42501'; end if;
 select * into c from ig_private.integration_config where id=p->>'id' for update;
 if c.id is null or c.version is distinct from (p->>'version')::int then raise exception 'Settings changed. Reload.' using errcode='40001'; end if;
 if jsonb_typeof(p->'settings')<>'object' or length((p->'settings')::text)>20000 or jsonb_typeof(p->'sealed')<>'object' or length((p->'sealed')::text)>40000 then raise exception 'Invalid settings'; end if;
 if (c.id='business' and p->>'mode'<>'active') or (c.id='razorpay' and p->>'mode' not in ('disabled','test','live')) or (c.id not in ('business','razorpay') and p->>'mode' not in ('disabled','enabled')) then raise exception 'Invalid integration mode'; end if;
 for k in select jsonb_object_keys(p->'settings') loop
  if k ~* 'secret|password|token|api_key' then raise exception 'Credentials must be encrypted'; end if;
 end loop;
 update ig_private.integration_config set mode=p->>'mode',settings=p->'settings',sealed=p->'sealed',credential_fields=array(select jsonb_array_elements_text(p->'credential_fields')),version=version+1,updated_by=auth.uid(),updated_at=now() where id=c.id returning * into c;
 perform ig_private.record_audit('integration.updated',c.id,jsonb_build_object('mode',c.mode,'version',c.version,'credential_fields',c.credential_fields));
 return to_jsonb(c)-'sealed'-'updated_by';
end $$;
create function public.ig_config_save(p jsonb) returns jsonb language sql security invoker set search_path='' as $$select ig_private.config_save(p)$$;
create function ig_private.business_public() returns jsonb language sql stable security definer set search_path='' as $$
 select settings from ig_private.integration_config where id='business'
$$;
create function public.ig_business_public() returns jsonb language sql security invoker set search_path='' as $$select ig_private.business_public()$$;
revoke all on function ig_private.business_public(),public.ig_business_public() from public;
grant execute on function ig_private.business_public(),public.ig_business_public() to anon,authenticated;
create function ig_private.policy_publish(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare k text; d jsonb=p->'documents'; release public.ig_policy_releases;
begin
 if not ig_private.allowed('settings.manage') then raise exception 'Super-user permission and MFA required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(7193344);
 if coalesce(p->>'legal_reviewed','false')<>'true' or p->>'previous_version' is distinct from ig_private.current_policy() then raise exception 'Confirm legal review and reload the current release'; end if;
 if jsonb_typeof(d) is distinct from 'object' or length(d::text)>160000 then raise exception 'Invalid policy bundle'; end if;
 foreach k in array array['privacy','terms','dataUse','cookies','commerce','refunds','shipping','grievances'] loop
  if jsonb_typeof(d->k) is distinct from 'object' or length(coalesce(d->k->>'title','')) not between 3 and 120 or length(coalesce(d->k->>'body','')) not between 200 and 30000 then raise exception 'Complete policy required: %',k; end if;
 end loop;
 update public.ig_policy_releases set current=false where current;
 insert into public.ig_policy_releases(version,documents,sha256,current,legal_reviewed,created_by) values(trim(p->>'version'),d,encode(extensions.digest(convert_to(d::text,'UTF8'),'sha256'),'hex'),true,true,auth.uid()) returning * into release;
 perform ig_private.record_audit('policies.published',release.version,jsonb_build_object('sha256',release.sha256));
 return to_jsonb(release);
end $$;
create function public.ig_policy_publish(p jsonb) returns jsonb language sql security invoker set search_path='' as $$select ig_private.policy_publish(p)$$;
revoke all on function ig_private.config_list(),public.ig_config_list(),ig_private.config_save(jsonb),public.ig_config_save(jsonb),ig_private.policy_publish(jsonb),public.ig_policy_publish(jsonb) from public,anon;
grant execute on function ig_private.config_list(),public.ig_config_list(),ig_private.config_save(jsonb),public.ig_config_save(jsonb),ig_private.policy_publish(jsonb),public.ig_policy_publish(jsonb) to authenticated;

-- Switch all protected operations to the current immutable policy release.
do $migration$
declare f text;s text;
begin
 foreach f in array array['ig_private.allowed(text)','ig_private.account_update_original(jsonb)','ig_private.room_manage_core(jsonb)'] loop
  select pg_get_functiondef(f::regprocedure) into s;
  s=replace(s,'''2026-11-11''','ig_private.current_policy()');execute s;
 end loop;
end $migration$;
alter function ig_private.account_update(jsonb) rename to account_update_policy_base;
revoke all on function ig_private.account_update_policy_base(jsonb) from public,anon,authenticated;
create function ig_private.account_update(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if p->>'action'='accept_policies' and coalesce(p->>'adult','false')<>'true' then raise exception 'Confirm that you are at least 18 and authorised to register'; end if;
 result=ig_private.account_update_policy_base(p);
 if p->>'action'='accept_policies' then
  update public.ig_consents set policy_hash=(select sha256 from public.ig_policy_releases where current) where id=(select max(id) from public.ig_consents where user_id=auth.uid() and purpose='registration');
 end if;
 return result;
end $$;
create or replace function public.ig_account_update(p jsonb) returns jsonb language sql security invoker set search_path='' as $$select ig_private.account_update(p)$$;
revoke all on function ig_private.account_update(jsonb) from public,anon;
grant execute on function ig_private.account_update(jsonb) to authenticated;

create table public.ig_privacy_requests(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),
 kind text not null check(kind in ('access','correction','withdrawal','closure','erasure','nomination','complaint')),
 detail text not null check(length(detail) between 10 and 4000),status text not null default 'received' check(status in ('received','in_review','resolved','declined')),
 response text not null default '' check(length(response)<=4000),version int not null default 1,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),acknowledge_by timestamptz not null default now()+interval '48 hours',resolve_by timestamptz not null default now()+interval '1 month'
);
alter table public.ig_privacy_requests enable row level security;
revoke all on public.ig_privacy_requests from anon,authenticated;
grant select on public.ig_privacy_requests to authenticated;
create policy privacy_request_read on public.ig_privacy_requests for select to authenticated using((user_id=(select auth.uid()) and (select ig_private.valid_identity())) or (select ig_private.allowed('settings.manage')));
create index ig_privacy_user on public.ig_privacy_requests(user_id,created_at desc);
create function ig_private.privacy_request(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.ig_privacy_requests;
begin
 if not ig_private.valid_identity() or not exists(select 1 from public.ig_profiles where id=auth.uid() and status='active') then raise exception 'Verified active account required' using errcode='42501'; end if;
 if p->>'action'='create' then
  if (select count(*) from public.ig_privacy_requests where user_id=auth.uid() and created_at>now()-interval '1 day')>=5 then raise exception 'Please use your existing request or contact hello@indiagully.com'; end if;
  insert into public.ig_privacy_requests(user_id,kind,detail) values(auth.uid(),p->>'kind',trim(p->>'detail')) returning * into r;
 elsif p->>'action'='review' then
  if not ig_private.allowed('settings.manage') then raise exception 'Super-user permission required' using errcode='42501'; end if;
  select * into r from public.ig_privacy_requests where id=(p->>'id')::uuid for update;
  if r.id is null or r.version is distinct from (p->>'version')::int then raise exception 'Request changed. Reload.' using errcode='40001'; end if;
  if length(trim(coalesce(p->>'response','')))<10 then raise exception 'Explain the decision or next action'; end if;
  update public.ig_privacy_requests set status=p->>'status',response=trim(p->>'response'),updated_at=now(),version=version+1 where id=r.id returning * into r;
 else raise exception 'Unknown request action';end if;
 perform ig_private.record_audit('privacy.'||(p->>'action'),r.id::text,jsonb_build_object('kind',r.kind,'status',r.status));
 return to_jsonb(r);
end $$;
create function public.ig_privacy_request(p jsonb) returns jsonb language sql security invoker set search_path='' as $$select ig_private.privacy_request(p)$$;
revoke all on function ig_private.privacy_request(jsonb),public.ig_privacy_request(jsonb) from public,anon;
grant execute on function ig_private.privacy_request(jsonb),public.ig_privacy_request(jsonb) to authenticated;

-- First policy release remains subject to legal review before commerce activation.
-- Initial policy text is an unpublished draft until explicit owner review.
insert into public.ig_policy_releases(version,documents,sha256,current) values('2026-11-11.2','{"privacy":{"title":"Privacy notice","body":"## Who is responsible\n\nIndia Gully is a brand of Vivacious Entertainment and Hospitality Private Limited, CIN U74999DL2017PTC323237, GSTIN 07AAGCV0867P1ZN. This notice covers the website, accounts, enquiries, procurement and controlled project information. Our current company and grievance contact details appear in the statutory information panel on this page. Write to hello@indiagully.com or call +91 8988988988.\n\n## Information and purposes\n\nWe process your name, work email, organisation, telephone number when supplied, enquiry and practice interests to respond to you and administer a requested service. Account records include authentication and security information, policy acceptances and your communication choices. Project access records include your NDA request, legal name, organisation, authority declaration, the accepted agreement, its version and hash, acceptance time, access approval and document activity. Procurement records may include billing and delivery details, GST particulars, accepted quotations, orders, payment references and correspondence. Do not submit Aadhaar, passport, card details, bank passwords or unrelated sensitive information through a general enquiry.\n\n## How we use and share information\n\nAuthorised India Gully personnel receive information relevant to their role, assigned practice and the service you request. Enquiries are routed to the designated India Gully team; hello@indiagully.com is our service reply address. Hosting, authentication, storage, payment and communication providers process information needed to operate their services. A seller, logistics partner, adviser or project counterparty receives relevant information only where required for your requested transaction, authorised disclosure or law. We do not sell account or enquiry data. We may disclose records to a competent authority when lawfully required and retain evidence needed to establish or defend a claim.\n\n## Payment information\n\nWhere online payment is enabled, the payment provider collects payment credentials through its own checkout. India Gully stores order and payment references, amount, currency and verification status. We do not ask for or store full card numbers, CVV, payment PINs or banking passwords. A browser success message is not final confirmation; payment is reconciled at the server.\n\n## Consent and communication choices\n\nInformation required to operate an account or fulfil a request is identified in the relevant form. Optional email marketing, SMS, personalisation and remarketing choices are separate and unticked by default. Refusing marketing does not prevent you from using the core service. You can change preferences in your account or request withdrawal by email. Withdrawal applies to future optional processing; necessary service messages, legal obligations and evidence of past transactions may continue. Browsing an opportunity alone does not authorise a marketing campaign or disclosure of a dossier.\n\n## Cookies and AI\n\nEssential cookies support authentication and security. Non-essential advertising or analytics tracking must remain off unless the applicable consent has been obtained. Our cookie notice describes the current implementation. An approved AI assistant may help staff prepare public editorial drafts; confidential project files and private customer records are excluded from that workflow. AI drafts require fact, rights and confidentiality review before publication. Enabling an external processor requires an assessment of purpose, access and the applicable notice.\n\n## Security and service locations\n\nAccess is controlled through authentication, staff MFA, role and practice permissions, project-specific grants and audit records. Data-room originals are held in private storage. Read-only previews may be watermarked, but no website can prevent every screenshot or copy by an authorised viewer. The application database is hosted in Mumbai. Hosting, email, payment and other providers may process technical or operational information in additional locations under their terms and applicable safeguards. We do not promise that every system log or backup remains exclusively in India.\n\n## Retention\n\nRecords are retained for the purpose for which they were collected and for applicable accounting, tax, contractual, security and dispute obligations. Enquiries that do not lead to an engagement are reviewed for deletion or anonymisation after 24 months of inactivity. Account information is reviewed on closure; transaction, consent, NDA and security evidence may need longer retention. Accounting and tax records follow the applicable statutory period, including extensions for proceedings or legal holds. Revoked data-room access does not erase an executed agreement or past audit trail. Backups expire under the relevant provider schedule. Deletion is subject to a documented review, rather than an unsupported promise of immediate removal from every backup.\n\n## Your requests and complaints\n\nYou may request access to relevant personal information, correction, withdrawal of optional consent, account closure or erasure. Where applicable law provides additional rights, including nomination, those rights remain available. Use the account privacy-request form or hello@indiagully.com. We may verify your identity and authority using proportionate information, explain any lawful retention or refusal and provide a tracking reference. Complaints follow the published grievance process. Statutory rights and access to competent authorities are not restricted by this notice.\n\n## Age and third-party information\n\nThe service is intended for adults who are at least 18 and authorised business representatives. Do not create an account on behalf of a child. If you submit another person''s information, ensure you have authority and limit it to what the request requires. Notify us if information has been submitted without authority.\n\n## Changes\n\nThe policy version and publication date are displayed here. Material changes are published as a new retained version. Registered users are asked to acknowledge the current registration policies before continuing protected account operations. A new policy does not retroactively change an executed NDA or accepted commercial agreement."},"dataUse":{"title":"Data usage policy","body":"## Necessary account and service processing\n\nYour verified contact information, account profile, security settings and policy acceptance are used to provide the account and the services you request. We record consent and authorisation evidence. Submitting a query permits us to respond and route it to the responsible India Gully team. It does not subscribe you to marketing.\n\n## Restricted information\n\nPublic teasers intentionally limit identifying information. Registration, policy acceptance or an enquiry does not execute an NDA or grant access to a project. An applicable project NDA must be accepted and reviewed, and an administrator must grant access to that specific data room. Access may expire or be revoked. Download rights are set separately for each room, client and file. You must not circumvent restrictions, share credentials, redistribute files or upload information without authority.\n\n## Optional personalisation and marketing\n\nYou choose communication channels and relevant practices separately in account preferences. Interest-based campaigns require the relevant current consent, an approved campaign, suppression checks and frequency limits. A dossier may be sent only where the recipient has the necessary project authorisation; consent to marketing alone is insufficient. You may withdraw optional consent without surrendering access to services that do not require it.\n\n## AI and automated assistance\n\nThe editorial assistant is limited to material expressly submitted for public-content drafting. It does not make legal decisions, approve a transaction, certify a valuation, grant data-room access or amend an executed agreement. Staff must verify generated content, commercial assertions and media rights. Private personal data and restricted documents must not be used as prompts in the public editorial workflow. Autonomous changes remain subject to permissions, version history and review; enabling a provider does not authorise unrestricted use of its services.\n\n## Responsible use and accountability\n\nYou are responsible for the accuracy and authority of information you submit. Notify India Gully of errors or suspected misuse. We may restrict access to protect confidential information, investigate abuse or comply with law. Business information, signed agreements and evidence needed for legal obligations may be retained after account closure. The privacy notice explains requests, service providers and retention."},"terms":{"title":"Website terms of use","body":"## The operator and your acceptance\n\nThis website is operated under the India Gully brand by Vivacious Entertainment and Hospitality Private Limited. Use the site lawfully. Account registration requires the current terms, privacy notice and data usage policy. You must be at least 18, provide accurate information and have authority to act for any organisation you represent. Keep credentials confidential and report suspected misuse promptly.\n\n## Scope of website information\n\nContent describes our practices and provides general commercial information. It is not an offer to sell securities, a lending commitment, a guarantee of return, a certified valuation or a substitute for legal, tax, investment, engineering or other regulated advice. An advisory appointment exists only on agreed engagement terms. A portfolio reference describes historical work and does not establish a current mandate, continuing affiliation or availability for sale.\n\n## Opportunities and diligence\n\nAsset descriptions and indicative commercial information may originate with owners, counterparties or third parties and may change. You must independently verify title, approvals, encumbrances, financial information, tax treatment, feasibility, regulatory eligibility and transaction documents with appropriate advisers. We may correct, withdraw or restrict a listing. An enquiry, NDA or data-room grant does not reserve an asset, qualify a bidder or create an obligation to transact.\n\n## CIRP, debt and special situations\n\nFor insolvency or restructuring opportunities, the authorised resolution professional, liquidator or other competent process authority and the official process documents govern participation, eligibility, deadlines, deposits and approvals. A website listing is not an official invitation or determination of eligibility, including eligibility under section 29A of the Insolvency and Bankruptcy Code where applicable. No outcome, creditor consent, tribunal order, financing or recovery is assured. Real-estate and regulated services require applicable registration and disclosure before they are offered; this website does not itself establish any regulatory registration.\n\n## Confidentiality and intellectual property\n\nAccess to confidential information is governed by the applicable project NDA and written authorisation. Ownership of confidential material remains with its owner. India Gully branding, original editorial content, designs and tools are protected by applicable intellectual-property rights. Limited personal or authorised business use does not permit scraping, republication, impersonation, automated extraction of restricted information or commercial reuse without permission. Third-party brands remain their owners'' property.\n\n## Acceptable use\n\nDo not submit unlawful, misleading or infringing material, malicious files, spam or information you are not authorised to disclose. Do not bypass authentication, access controls, rate limits or download restrictions. We may suspend or close access for a substantiated security, legal or contractual reason and preserve relevant evidence. A reasonable opportunity to seek review remains available through the grievance channel where practicable.\n\n## Valuation tools\n\nCalculators generate indicative scenarios from the assumptions entered. They do not inspect an asset or independently verify inputs. Results are not certified valuations, investment advice or lending decisions. Actual outcomes may differ materially. Use qualified professionals and asset-specific diligence before relying on a result for a transaction.\n\n## Liability and rights preserved\n\nWe use reasonable care in operating the website but do not guarantee uninterrupted access or the accuracy of third-party material. To the extent permitted by law, India Gully is not liable for indirect or consequential loss arising solely from general website information or unauthorised use. This provision does not exclude liability that cannot lawfully be excluded, including applicable consumer rights, fraud or wilful misconduct. A signed engagement or accepted order governs the relevant paid service. You remain responsible for losses caused by your unlawful misuse, unauthorised disclosure or infringement, to the extent established under applicable law.\n\n## Governing law and complaints\n\nIndian law governs these terms. Competent courts and statutory forums retain the jurisdiction provided by law; no term removes a consumer''s right to approach an appropriate forum. A separate signed agreement may contain a lawful dispute-resolution clause for that engagement. Contact hello@indiagully.com before escalating a website issue so that we can investigate and respond. Changes to these terms are published as a new version and do not retrospectively rewrite an accepted contract."},"cookies":{"title":"Cookie and tracking notice","body":"## Essential storage\n\nAuthentication cookies and local browser storage maintain sign-in, session refresh and security. The hosting service may use essential protection cookies. These are required for protected account functions. Clearing them or blocking essential storage may sign you out or prevent those functions from working.\n\n## Optional tracking\n\nAdvertising pixels, remarketing tags and non-essential behavioural analytics are not currently installed. A recorded account preference does not itself install tracking. Any future optional tracking must be disclosed with its provider and purpose and kept inactive until the required choice has been made. Rejecting optional tracking must be as accessible as accepting it.\n\n## Your controls\n\nUse your browser settings to inspect and clear cookies. Change optional communication and personalisation preferences in your account. Contact hello@indiagully.com for questions about website storage. Payment-provider checkout may use its own necessary security storage, governed by that provider''s notice."},"commerce":{"title":"HORECA procurement and payment terms","body":"## Quotations and the contracting party\n\nIndia Gully''s contracting entity is Vivacious Entertainment and Hospitality Private Limited, GSTIN 07AAGCV0867P1ZN. A catalogue enquiry is a request for a quotation. Product availability, specifications, seller identity, quantity, prices, applicable GST, freight, installation, lead time and warranty must be stated in the approved quotation or order before payment. Where another seller contracts directly, that fact and the seller''s details must be disclosed before acceptance. We do not operate an undisclosed third-party payment collection arrangement.\n\n## Acceptance and scope\n\nOnly the version of the quotation presented and accepted through your verified account is payable. Check item descriptions, quantities, delivery address, billing particulars and tax treatment before accepting. Product substitutions, changes in quantity or scope and additional charges require your agreement. An indicative catalogue price or an automated acknowledgement is not an unconditional order acceptance.\n\n## Payments\n\nOnline payments, when available, are processed by Razorpay in Indian rupees for the approved amount. The final total includes the taxes and other charges displayed in the accepted quote. We verify the order, payment signature, amount, currency and captured status at the server. A payment reference or browser confirmation alone is not proof of final settlement. We do not receive or store your banking password, CVV or payment PIN. Never pay an individual account or a payment link that cannot be verified with India Gully.\n\n## Supply, warranties and inspection\n\nThe accepted order identifies the delivery terms, installation scope and applicable manufacturer or supplier warranty. Inspect consignments reasonably promptly and report visible damage, shortage or incorrect supply with the order reference and available evidence. A requested reporting period assists investigation and does not extinguish rights that cannot legally be waived. Product performance must be assessed against the agreed specification and applicable law.\n\n## Business and consumer purchases\n\nCommercial procurement terms may be agreed for a business order. Where you qualify as a consumer under applicable law, mandatory consumer protections prevail over an inconsistent term. We do not impose blanket exclusions for defective, misdescribed or unlawfully supplied goods. Cancellation, refund and delivery information appears in the linked policies and the specific quotation.\n\n## Invoices, complaints and records\n\nProvide accurate GST and billing details before invoicing. Payment receipts and tax invoices are distinct documents; a payment status page is not a GST invoice. Statutory invoice particulars and applicable e-invoicing or e-way-bill requirements must be handled for the actual supply. Keep your accepted quote and order reference. Raise a complaint through the grievance channel or hello@indiagully.com. Nothing here excludes statutory remedies."},"refunds":{"title":"Cancellation, returns and refunds","body":"## Before an order is confirmed\n\nYou may withdraw an unaccepted quotation request without a purchase obligation. For an accepted order, contact hello@indiagully.com with the quotation or payment reference. Cancellation feasibility depends on the disclosed order terms and whether procurement, custom manufacture or dispatch has begun. Any non-recoverable cost must be supported, proportionate and permitted by the agreement and applicable law.\n\n## Incorrect, damaged or defective supply\n\nReport the issue with the order reference, description and available photographs. We will investigate with the relevant supplier and arrange the remedy required by the accepted specification, warranty and applicable law. Do not return heavy or installed equipment without collection instructions. This process does not remove statutory rights or impose a blanket no-refund rule.\n\n## Custom and made-to-order items\n\nRestrictions on cancellation or change of mind for custom products must be clearly disclosed and accepted before payment. They do not excuse a defect, misdescription, failure to supply or other obligation imposed by law. An additional charge or deduction will be explained before a voluntary settlement is agreed.\n\n## Refund handling\n\nAn approved refund is returned through the original payment channel where supported, after verification of the payment and the applicable remedy. We will communicate approval or rejection with reasons and the expected processing period. Bank or gateway processing time may vary. Do not share banking passwords or OTPs to obtain a refund. A pending refund remains trackable against its reference; a provider acknowledgement is not treated as completed credit.\n\n## Duplicate or failed payments\n\nContact us if your account is debited without an order confirmation or a payment appears duplicated. We reconcile provider records before issuing another payment request or refund. Do not repeat a payment solely because the browser closed. Complaint handling and statutory escalation remain available."},"shipping":{"title":"Delivery and fulfilment","body":"## Delivery before you pay\n\nThe approved quotation states the delivery destination, freight and handling charges, indicative lead time, dispatch dependencies and any installation or site-access requirements. We do not display a universal delivery promise for made-to-order or project procurement. Any material change is communicated for your agreement before proceeding.\n\n## Dispatch and receipt\n\nDelivery details are shared when dispatch is confirmed. Arrange safe access, unloading and authorised receipt where these are your responsibilities under the order. Record visible damage or shortage when reasonably possible and contact hello@indiagully.com with supporting details. Risk and title pass as stated in the accepted order, subject to applicable law.\n\n## Delays and inability to supply\n\nWe will explain a known material delay, revised estimate and available options. An event outside reasonable control does not remove mandatory refund or consumer remedies. If an agreed supply cannot be completed, the applicable cancellation and refund process will be followed. Substitution requires agreement.\n\n## Service delivery\n\nAdvisory, design coordination, PMC and other professional services follow the milestones and dependencies in the separate engagement. Paying a procurement quotation does not appoint India Gully for an unrelated advisory service."},"grievances":{"title":"Grievances and privacy requests","body":"## Raise a concern\n\nWrite to hello@indiagully.com or call +91 8988988988. Registered users can also submit a privacy or service request from their account and retain the tracking reference. Include the relevant order, enquiry or project reference and a clear description, but do not include passwords, OTPs, card credentials or unnecessary identity documents.\n\n## Handling and escalation\n\nWe record the complaint, acknowledge consumer grievances within 48 hours and seek to resolve them within one month of receipt, subject to any shorter applicable requirement. We may request proportionate information to verify identity, authority or the issue. The response will explain the action taken, any outstanding dependency and the available escalation. The appointed grievance officer''s confirmed name, designation and contact details must be displayed in the statutory information panel before public commerce activation.\n\n## Privacy requests\n\nYou can seek access, correction, withdrawal of optional consent, account closure or erasure. A request is assessed against applicable rights, transaction obligations, confidentiality and lawful retention requirements. We explain any information that must be retained and record the decision. Closing an account and deleting every business record are different actions. You may complain about the handling of a request through this same channel.\n\n## Statutory remedies\n\nThis process does not restrict access to the National Consumer Helpline, a competent consumer commission, the applicable data-protection authority or any other lawful remedy. Where a particular authority''s jurisdiction or a statutory right has not yet commenced, the applicable commencement provisions govern. Suspected account compromise or confidential-data exposure should be reported promptly with the subject Security incident."}}'::jsonb,encode(extensions.digest(convert_to(('{"privacy":{"title":"Privacy notice","body":"## Who is responsible\n\nIndia Gully is a brand of Vivacious Entertainment and Hospitality Private Limited, CIN U74999DL2017PTC323237, GSTIN 07AAGCV0867P1ZN. This notice covers the website, accounts, enquiries, procurement and controlled project information. Our current company and grievance contact details appear in the statutory information panel on this page. Write to hello@indiagully.com or call +91 8988988988.\n\n## Information and purposes\n\nWe process your name, work email, organisation, telephone number when supplied, enquiry and practice interests to respond to you and administer a requested service. Account records include authentication and security information, policy acceptances and your communication choices. Project access records include your NDA request, legal name, organisation, authority declaration, the accepted agreement, its version and hash, acceptance time, access approval and document activity. Procurement records may include billing and delivery details, GST particulars, accepted quotations, orders, payment references and correspondence. Do not submit Aadhaar, passport, card details, bank passwords or unrelated sensitive information through a general enquiry.\n\n## How we use and share information\n\nAuthorised India Gully personnel receive information relevant to their role, assigned practice and the service you request. Enquiries are routed to the designated India Gully team; hello@indiagully.com is our service reply address. Hosting, authentication, storage, payment and communication providers process information needed to operate their services. A seller, logistics partner, adviser or project counterparty receives relevant information only where required for your requested transaction, authorised disclosure or law. We do not sell account or enquiry data. We may disclose records to a competent authority when lawfully required and retain evidence needed to establish or defend a claim.\n\n## Payment information\n\nWhere online payment is enabled, the payment provider collects payment credentials through its own checkout. India Gully stores order and payment references, amount, currency and verification status. We do not ask for or store full card numbers, CVV, payment PINs or banking passwords. A browser success message is not final confirmation; payment is reconciled at the server.\n\n## Consent and communication choices\n\nInformation required to operate an account or fulfil a request is identified in the relevant form. Optional email marketing, SMS, personalisation and remarketing choices are separate and unticked by default. Refusing marketing does not prevent you from using the core service. You can change preferences in your account or request withdrawal by email. Withdrawal applies to future optional processing; necessary service messages, legal obligations and evidence of past transactions may continue. Browsing an opportunity alone does not authorise a marketing campaign or disclosure of a dossier.\n\n## Cookies and AI\n\nEssential cookies support authentication and security. Non-essential advertising or analytics tracking must remain off unless the applicable consent has been obtained. Our cookie notice describes the current implementation. An approved AI assistant may help staff prepare public editorial drafts; confidential project files and private customer records are excluded from that workflow. AI drafts require fact, rights and confidentiality review before publication. Enabling an external processor requires an assessment of purpose, access and the applicable notice.\n\n## Security and service locations\n\nAccess is controlled through authentication, staff MFA, role and practice permissions, project-specific grants and audit records. Data-room originals are held in private storage. Read-only previews may be watermarked, but no website can prevent every screenshot or copy by an authorised viewer. The application database is hosted in Mumbai. Hosting, email, payment and other providers may process technical or operational information in additional locations under their terms and applicable safeguards. We do not promise that every system log or backup remains exclusively in India.\n\n## Retention\n\nRecords are retained for the purpose for which they were collected and for applicable accounting, tax, contractual, security and dispute obligations. Enquiries that do not lead to an engagement are reviewed for deletion or anonymisation after 24 months of inactivity. Account information is reviewed on closure; transaction, consent, NDA and security evidence may need longer retention. Accounting and tax records follow the applicable statutory period, including extensions for proceedings or legal holds. Revoked data-room access does not erase an executed agreement or past audit trail. Backups expire under the relevant provider schedule. Deletion is subject to a documented review, rather than an unsupported promise of immediate removal from every backup.\n\n## Your requests and complaints\n\nYou may request access to relevant personal information, correction, withdrawal of optional consent, account closure or erasure. Where applicable law provides additional rights, including nomination, those rights remain available. Use the account privacy-request form or hello@indiagully.com. We may verify your identity and authority using proportionate information, explain any lawful retention or refusal and provide a tracking reference. Complaints follow the published grievance process. Statutory rights and access to competent authorities are not restricted by this notice.\n\n## Age and third-party information\n\nThe service is intended for adults who are at least 18 and authorised business representatives. Do not create an account on behalf of a child. If you submit another person''s information, ensure you have authority and limit it to what the request requires. Notify us if information has been submitted without authority.\n\n## Changes\n\nThe policy version and publication date are displayed here. Material changes are published as a new retained version. Registered users are asked to acknowledge the current registration policies before continuing protected account operations. A new policy does not retroactively change an executed NDA or accepted commercial agreement."},"dataUse":{"title":"Data usage policy","body":"## Necessary account and service processing\n\nYour verified contact information, account profile, security settings and policy acceptance are used to provide the account and the services you request. We record consent and authorisation evidence. Submitting a query permits us to respond and route it to the responsible India Gully team. It does not subscribe you to marketing.\n\n## Restricted information\n\nPublic teasers intentionally limit identifying information. Registration, policy acceptance or an enquiry does not execute an NDA or grant access to a project. An applicable project NDA must be accepted and reviewed, and an administrator must grant access to that specific data room. Access may expire or be revoked. Download rights are set separately for each room, client and file. You must not circumvent restrictions, share credentials, redistribute files or upload information without authority.\n\n## Optional personalisation and marketing\n\nYou choose communication channels and relevant practices separately in account preferences. Interest-based campaigns require the relevant current consent, an approved campaign, suppression checks and frequency limits. A dossier may be sent only where the recipient has the necessary project authorisation; consent to marketing alone is insufficient. You may withdraw optional consent without surrendering access to services that do not require it.\n\n## AI and automated assistance\n\nThe editorial assistant is limited to material expressly submitted for public-content drafting. It does not make legal decisions, approve a transaction, certify a valuation, grant data-room access or amend an executed agreement. Staff must verify generated content, commercial assertions and media rights. Private personal data and restricted documents must not be used as prompts in the public editorial workflow. Autonomous changes remain subject to permissions, version history and review; enabling a provider does not authorise unrestricted use of its services.\n\n## Responsible use and accountability\n\nYou are responsible for the accuracy and authority of information you submit. Notify India Gully of errors or suspected misuse. We may restrict access to protect confidential information, investigate abuse or comply with law. Business information, signed agreements and evidence needed for legal obligations may be retained after account closure. The privacy notice explains requests, service providers and retention."},"terms":{"title":"Website terms of use","body":"## The operator and your acceptance\n\nThis website is operated under the India Gully brand by Vivacious Entertainment and Hospitality Private Limited. Use the site lawfully. Account registration requires the current terms, privacy notice and data usage policy. You must be at least 18, provide accurate information and have authority to act for any organisation you represent. Keep credentials confidential and report suspected misuse promptly.\n\n## Scope of website information\n\nContent describes our practices and provides general commercial information. It is not an offer to sell securities, a lending commitment, a guarantee of return, a certified valuation or a substitute for legal, tax, investment, engineering or other regulated advice. An advisory appointment exists only on agreed engagement terms. A portfolio reference describes historical work and does not establish a current mandate, continuing affiliation or availability for sale.\n\n## Opportunities and diligence\n\nAsset descriptions and indicative commercial information may originate with owners, counterparties or third parties and may change. You must independently verify title, approvals, encumbrances, financial information, tax treatment, feasibility, regulatory eligibility and transaction documents with appropriate advisers. We may correct, withdraw or restrict a listing. An enquiry, NDA or data-room grant does not reserve an asset, qualify a bidder or create an obligation to transact.\n\n## CIRP, debt and special situations\n\nFor insolvency or restructuring opportunities, the authorised resolution professional, liquidator or other competent process authority and the official process documents govern participation, eligibility, deadlines, deposits and approvals. A website listing is not an official invitation or determination of eligibility, including eligibility under section 29A of the Insolvency and Bankruptcy Code where applicable. No outcome, creditor consent, tribunal order, financing or recovery is assured. Real-estate and regulated services require applicable registration and disclosure before they are offered; this website does not itself establish any regulatory registration.\n\n## Confidentiality and intellectual property\n\nAccess to confidential information is governed by the applicable project NDA and written authorisation. Ownership of confidential material remains with its owner. India Gully branding, original editorial content, designs and tools are protected by applicable intellectual-property rights. Limited personal or authorised business use does not permit scraping, republication, impersonation, automated extraction of restricted information or commercial reuse without permission. Third-party brands remain their owners'' property.\n\n## Acceptable use\n\nDo not submit unlawful, misleading or infringing material, malicious files, spam or information you are not authorised to disclose. Do not bypass authentication, access controls, rate limits or download restrictions. We may suspend or close access for a substantiated security, legal or contractual reason and preserve relevant evidence. A reasonable opportunity to seek review remains available through the grievance channel where practicable.\n\n## Valuation tools\n\nCalculators generate indicative scenarios from the assumptions entered. They do not inspect an asset or independently verify inputs. Results are not certified valuations, investment advice or lending decisions. Actual outcomes may differ materially. Use qualified professionals and asset-specific diligence before relying on a result for a transaction.\n\n## Liability and rights preserved\n\nWe use reasonable care in operating the website but do not guarantee uninterrupted access or the accuracy of third-party material. To the extent permitted by law, India Gully is not liable for indirect or consequential loss arising solely from general website information or unauthorised use. This provision does not exclude liability that cannot lawfully be excluded, including applicable consumer rights, fraud or wilful misconduct. A signed engagement or accepted order governs the relevant paid service. You remain responsible for losses caused by your unlawful misuse, unauthorised disclosure or infringement, to the extent established under applicable law.\n\n## Governing law and complaints\n\nIndian law governs these terms. Competent courts and statutory forums retain the jurisdiction provided by law; no term removes a consumer''s right to approach an appropriate forum. A separate signed agreement may contain a lawful dispute-resolution clause for that engagement. Contact hello@indiagully.com before escalating a website issue so that we can investigate and respond. Changes to these terms are published as a new version and do not retrospectively rewrite an accepted contract."},"cookies":{"title":"Cookie and tracking notice","body":"## Essential storage\n\nAuthentication cookies and local browser storage maintain sign-in, session refresh and security. The hosting service may use essential protection cookies. These are required for protected account functions. Clearing them or blocking essential storage may sign you out or prevent those functions from working.\n\n## Optional tracking\n\nAdvertising pixels, remarketing tags and non-essential behavioural analytics are not currently installed. A recorded account preference does not itself install tracking. Any future optional tracking must be disclosed with its provider and purpose and kept inactive until the required choice has been made. Rejecting optional tracking must be as accessible as accepting it.\n\n## Your controls\n\nUse your browser settings to inspect and clear cookies. Change optional communication and personalisation preferences in your account. Contact hello@indiagully.com for questions about website storage. Payment-provider checkout may use its own necessary security storage, governed by that provider''s notice."},"commerce":{"title":"HORECA procurement and payment terms","body":"## Quotations and the contracting party\n\nIndia Gully''s contracting entity is Vivacious Entertainment and Hospitality Private Limited, GSTIN 07AAGCV0867P1ZN. A catalogue enquiry is a request for a quotation. Product availability, specifications, seller identity, quantity, prices, applicable GST, freight, installation, lead time and warranty must be stated in the approved quotation or order before payment. Where another seller contracts directly, that fact and the seller''s details must be disclosed before acceptance. We do not operate an undisclosed third-party payment collection arrangement.\n\n## Acceptance and scope\n\nOnly the version of the quotation presented and accepted through your verified account is payable. Check item descriptions, quantities, delivery address, billing particulars and tax treatment before accepting. Product substitutions, changes in quantity or scope and additional charges require your agreement. An indicative catalogue price or an automated acknowledgement is not an unconditional order acceptance.\n\n## Payments\n\nOnline payments, when available, are processed by Razorpay in Indian rupees for the approved amount. The final total includes the taxes and other charges displayed in the accepted quote. We verify the order, payment signature, amount, currency and captured status at the server. A payment reference or browser confirmation alone is not proof of final settlement. We do not receive or store your banking password, CVV or payment PIN. Never pay an individual account or a payment link that cannot be verified with India Gully.\n\n## Supply, warranties and inspection\n\nThe accepted order identifies the delivery terms, installation scope and applicable manufacturer or supplier warranty. Inspect consignments reasonably promptly and report visible damage, shortage or incorrect supply with the order reference and available evidence. A requested reporting period assists investigation and does not extinguish rights that cannot legally be waived. Product performance must be assessed against the agreed specification and applicable law.\n\n## Business and consumer purchases\n\nCommercial procurement terms may be agreed for a business order. Where you qualify as a consumer under applicable law, mandatory consumer protections prevail over an inconsistent term. We do not impose blanket exclusions for defective, misdescribed or unlawfully supplied goods. Cancellation, refund and delivery information appears in the linked policies and the specific quotation.\n\n## Invoices, complaints and records\n\nProvide accurate GST and billing details before invoicing. Payment receipts and tax invoices are distinct documents; a payment status page is not a GST invoice. Statutory invoice particulars and applicable e-invoicing or e-way-bill requirements must be handled for the actual supply. Keep your accepted quote and order reference. Raise a complaint through the grievance channel or hello@indiagully.com. Nothing here excludes statutory remedies."},"refunds":{"title":"Cancellation, returns and refunds","body":"## Before an order is confirmed\n\nYou may withdraw an unaccepted quotation request without a purchase obligation. For an accepted order, contact hello@indiagully.com with the quotation or payment reference. Cancellation feasibility depends on the disclosed order terms and whether procurement, custom manufacture or dispatch has begun. Any non-recoverable cost must be supported, proportionate and permitted by the agreement and applicable law.\n\n## Incorrect, damaged or defective supply\n\nReport the issue with the order reference, description and available photographs. We will investigate with the relevant supplier and arrange the remedy required by the accepted specification, warranty and applicable law. Do not return heavy or installed equipment without collection instructions. This process does not remove statutory rights or impose a blanket no-refund rule.\n\n## Custom and made-to-order items\n\nRestrictions on cancellation or change of mind for custom products must be clearly disclosed and accepted before payment. They do not excuse a defect, misdescription, failure to supply or other obligation imposed by law. An additional charge or deduction will be explained before a voluntary settlement is agreed.\n\n## Refund handling\n\nAn approved refund is returned through the original payment channel where supported, after verification of the payment and the applicable remedy. We will communicate approval or rejection with reasons and the expected processing period. Bank or gateway processing time may vary. Do not share banking passwords or OTPs to obtain a refund. A pending refund remains trackable against its reference; a provider acknowledgement is not treated as completed credit.\n\n## Duplicate or failed payments\n\nContact us if your account is debited without an order confirmation or a payment appears duplicated. We reconcile provider records before issuing another payment request or refund. Do not repeat a payment solely because the browser closed. Complaint handling and statutory escalation remain available."},"shipping":{"title":"Delivery and fulfilment","body":"## Delivery before you pay\n\nThe approved quotation states the delivery destination, freight and handling charges, indicative lead time, dispatch dependencies and any installation or site-access requirements. We do not display a universal delivery promise for made-to-order or project procurement. Any material change is communicated for your agreement before proceeding.\n\n## Dispatch and receipt\n\nDelivery details are shared when dispatch is confirmed. Arrange safe access, unloading and authorised receipt where these are your responsibilities under the order. Record visible damage or shortage when reasonably possible and contact hello@indiagully.com with supporting details. Risk and title pass as stated in the accepted order, subject to applicable law.\n\n## Delays and inability to supply\n\nWe will explain a known material delay, revised estimate and available options. An event outside reasonable control does not remove mandatory refund or consumer remedies. If an agreed supply cannot be completed, the applicable cancellation and refund process will be followed. Substitution requires agreement.\n\n## Service delivery\n\nAdvisory, design coordination, PMC and other professional services follow the milestones and dependencies in the separate engagement. Paying a procurement quotation does not appoint India Gully for an unrelated advisory service."},"grievances":{"title":"Grievances and privacy requests","body":"## Raise a concern\n\nWrite to hello@indiagully.com or call +91 8988988988. Registered users can also submit a privacy or service request from their account and retain the tracking reference. Include the relevant order, enquiry or project reference and a clear description, but do not include passwords, OTPs, card credentials or unnecessary identity documents.\n\n## Handling and escalation\n\nWe record the complaint, acknowledge consumer grievances within 48 hours and seek to resolve them within one month of receipt, subject to any shorter applicable requirement. We may request proportionate information to verify identity, authority or the issue. The response will explain the action taken, any outstanding dependency and the available escalation. The appointed grievance officer''s confirmed name, designation and contact details must be displayed in the statutory information panel before public commerce activation.\n\n## Privacy requests\n\nYou can seek access, correction, withdrawal of optional consent, account closure or erasure. A request is assessed against applicable rights, transaction obligations, confidentiality and lawful retention requirements. We explain any information that must be retained and record the decision. Closing an account and deleting every business record are different actions. You may complain about the handling of a request through this same channel.\n\n## Statutory remedies\n\nThis process does not restrict access to the National Consumer Helpline, a competent consumer commission, the applicable data-protection authority or any other lawful remedy. Where a particular authority''s jurisdiction or a statutory right has not yet commenced, the applicable commencement provisions govern. Suspected account compromise or confidential-data exposure should be reported promptly with the subject Security incident."}}'::jsonb)::text,'UTF8'),'sha256'),'hex'),false);
